def compute(vars):
    settlements = [vars["v1"], vars["v2"], vars["v3"]]
    total = sum(settlements)
    average = total / len(settlements)
    return {
        "value": average,
        "trace": {
            "settlements": settlements,
            "total": total,
            "count": len(settlements),
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
